"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { ArrowLeft, Bot, MessageSquare, Plus } from "@workpal/ui/icons";
import { toast } from "sonner";
import { Button } from "@workpal/ui/components/ui/button";
import { IconButton } from "@workpal/ui/components/common/icon-button";
import { useIsCompact } from "@workpal/ui/hooks/use-mobile";
import { useRequiredWorkspaceSlug, useWorkspacePaths } from "@workpal/core/paths";
import { getCurrentSlug } from "@workpal/core/platform";
import { useChatStore } from "@workpal/core/chat";
import { chatQuickActionsPendingOptions } from "@workpal/core/chat/queries";
import { useRegenerateChatQuickActions } from "@workpal/core/chat/mutations";
import { useQuickActionsPendingTimeout } from "@workpal/core/chat/use-quick-actions-pending-timeout";
import { useQuickActionsFailureToast } from "./components/use-quick-actions-failure-toast";
import { useQuery } from "@tanstack/react-query";
import type { Agent, ChatSession } from "@workpal/core/types";
import { CollectionPageState } from "../layout/collection-page";
import { CollapsedNavTrigger, PageHeader } from "../layout/page-header";
import { PanelHeader } from "../layout/panel-nav";
import { useListColumnCollapsed } from "../layout/app-shell-context";
import { ListColumn } from "../layout/list-column";
import { useNavigation } from "../navigation";
import { useT } from "../i18n";
import { ChatMessageList, ChatMessageSkeleton } from "./components/chat-message-list";
import { ChatInput } from "./components/chat-input";
import { ChatQueue } from "./components/chat-queue";
import { ChatWakeupStrip, useChatWakeups } from "./components/chat-wakeups";
import { ChatThreadList } from "./components/chat-thread-list";
import { ChatSessionHeader } from "./components/chat-session-header";
import { EmptyState } from "./components/chat-empty-state";
import { NewChatButton } from "./components/new-chat-button";
import { useChatController } from "./components/use-chat-controller";
import { useChatAnnotations } from "./components/use-chat-annotations";
import { OfflineBanner } from "./components/offline-banner";
import { NoAgentBanner } from "./components/no-agent-banner";
import { ArchivedAgentBanner } from "./components/archived-agent-banner";
import { AgentAccessRevokedBanner } from "./components/agent-access-revoked-banner";
import { RuntimeRequiredBanner } from "./components/runtime-required-banner";
import { ChatAppRequests } from "../common/app-requests";
import { useRegisterCommandBarContext } from "../search/register-context";

/**
 * Chat tab — the first-class two-pane surface (thread list on the left,
 * conversation on the right), mirroring the Inbox page layout. Shares all
 * conversation logic with the floating FAB via `useChatController`; the
 * left rail reuses `ChatThreadList`.
 *
 * Selection is URL-addressable via `?session=<id>` so a thread can be
 * deep-linked, opened from a notification, and survive refresh. The chat
 * store's `activeSessionId` stays the source of truth (both surfaces read
 * it); the URL is kept in sync in both directions. `?agent=<id>` is the
 * complementary one-shot deep link for a NEW chat: it starts a fresh compose
 * bound to that agent and is then stripped from the URL.
 *
 * Starting a chat is where the agent is chosen: the header ⊕ opens an agent
 * picker (see NewChatButton), so the compose box no longer needs its own
 * agent selector. Unlike the FAB, this page passes no `contextItems` to
 * `ChatInput`, so its `@` mentions fall back to manual search (issue-comment
 * style).
 */
export function ChatPage() {
  const { t } = useT("chat");
  const { pathname, searchParams, push, replace } = useNavigation();
  const workspaceSlug = useRequiredWorkspaceSlug();
  const wsPaths = useWorkspacePaths();
  // App Router can retain this page after navigation. Once the URL belongs
  // to another route, this instance must stop reconciling shared chat state.
  // Also check the live workspace mirror in each effect: the incoming layout
  // can rehydrate the store before this page observes the destination URL.
  const isCurrentChatRoute = pathname === wsPaths.chat();
  const isCompact = useIsCompact();

  const c = useChatController({
    isActive: isCurrentChatRoute && getCurrentSlug() === workspaceSlug,
  });
  const { data: quickActionsPending = null } = useQuery(
    chatQuickActionsPendingOptions(c.activeSessionId ?? ""),
  );
  // Drop a stuck pending marker (dead daemon / failed supplement) so the pill
  // spinner stops and a later refresh starts clean (MUL-5149).
  useQuickActionsPendingTimeout(c.activeSessionId ?? null, quickActionsPending);
  // Toast when an accepted refresh later fails in the daemon (async half).
  useQuickActionsFailureToast(c.activeSessionId ?? null);
  const wakeups = useChatWakeups(c.activeSessionId);
  const regenerateQuickActions = useRegenerateChatQuickActions();
  const annotations = useChatAnnotations({
    sessionId: c.activeSessionId,
    agentName: c.activeAgent?.name,
    enabled: !c.isSessionArchived && !c.isAgentArchived && !c.isAgentAccessRevoked && c.isAgentRuntimeBound && !c.noAgent,
  });
  const urlSession = searchParams.get("session") || null;
  const urlAgent = searchParams.get("agent") || null;

  // "Composing a brand-new chat" — the user hit ⊕ but hasn't sent yet, so no
  // session exists. At compact widths this decides list-vs-conversation; on desktop the
  // conversation pane is always mounted so it only needs to reset itself once a
  // real session takes over.
  const [composingNew, setComposingNew] = useState(false);
  useEffect(() => {
    // Read the LIVE store value for the same reason as the session sync
    // effects below: under StrictMode's double-invoke this effect replays
    // with the render-captured snapshot, and a stale non-null session (a
    // persisted chat the URL→store effect already cleared) would revert the
    // composingNew=true that the later `?agent=` intent effect just set.
    if (useChatStore.getState().activeSessionId) setComposingNew(false);
  }, [c.activeSessionId]);

  // Two-way sync between the URL (`?session=`) and the chat store's
  // activeSessionId. Both effects read the LIVE store value via
  // `useChatStore.getState()` rather than the render-captured `c.activeSessionId`.
  // That is what keeps them from fighting on mount: a naive mirror effect fires
  // with the stale (null) snapshot and "corrects" the URL by stripping the
  // session before the URL→store effect has applied — breaking deep links and
  // making selection / new-chat feel unresponsive. Reading getState() sees the
  // value the sibling effect just wrote, so the reconciliation converges in one
  // pass and is idempotent under StrictMode's double-invoke.

  // URL → store: deep link, refresh, notification click, back/forward.
  useEffect(() => {
    if (!isCurrentChatRoute || getCurrentSlug() !== workspaceSlug) return;
    if (urlSession !== useChatStore.getState().activeSessionId) {
      c.setActiveSession(urlSession);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps -- reconcile URL/route changes, not store updates
  }, [isCurrentChatRoute, workspaceSlug, urlSession]);

  // store → URL: thread selection, "new chat", and sessions created by sending.
  useEffect(() => {
    if (!isCurrentChatRoute || getCurrentSlug() !== workspaceSlug) return;
    const live = useChatStore.getState().activeSessionId;
    const current = searchParams.get("session") || null;
    if (live !== current) {
      const base = wsPaths.chat();
      replace(live ? `${base}?session=${live}` : base);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps -- reconcile store/route changes, not URL updates
  }, [isCurrentChatRoute, workspaceSlug, c.activeSessionId]);

  const listCollapsed = useListColumnCollapsed();

  // `?agent=` intent bookkeeping. The ref holds the param value already
  // consumed (or superseded) so the effect below fires at most once per deep
  // link — it also bridges the async window between replace() and the
  // searchParams actually dropping the param. Any explicit user action must
  // supersede a still-pending intent: agent/member queries can resolve late,
  // and a deferred intent firing after the user picked a thread (or started
  // another chat) would clobber that choice.
  const consumedAgentIntent = useRef<string | null>(null);
  const supersedeAgentIntent = () => {
    if (urlAgent) consumedAgentIntent.current = urlAgent;
  };

  const handleSelect = (session: ChatSession) => {
    supersedeAgentIntent();
    c.handleSelectSession(session);
    setComposingNew(false);
  };

  // Single archive path for both entry points (thread-list row + conversation
  // header). When the archived chat is the one in view, move the pane off it:
  // on desktop advance to the next chat (Inbox-style); when compact drop back to
  // the list, which reads more naturally than being thrown into an unrelated
  // conversation full-screen. Archiving any other chat leaves the view put.
  const handleArchive = (session: ChatSession) => {
    supersedeAgentIntent();
    if (session.id === c.activeSessionId) {
      if (isCompact) {
        c.setActiveSession(null);
        setComposingNew(false);
      } else {
        c.advanceSelectionAfterArchive(session);
      }
    }
    c.archiveSession(session.id);
  };

  const startNewChat = (agent: Agent | null) => {
    // A manual ⊕ pick outranks a pending deep link; when called FROM the
    // intent effect the ref is already set to this param, so this is a no-op.
    supersedeAgentIntent();
    if (agent) c.handleStartNewChat(agent);
    else c.handleNewChat();
    setComposingNew(true);
  };

  const changeProjectContext = (projectId: string | null) => {
    if (projectId === c.activeProjectId) return;
    c.handleProjectChange(projectId);
    // Removing a project stays in the current conversation. Choosing a
    // project for an existing conversation starts a clean session, and a
    // compact layout must stay in the compose pane after activeSessionId is
    // cleared.
    if (!c.currentSession || projectId !== null) setComposingNew(true);
  };

  // The command bar calls the page's own handlers so archiving or re-scoping
  // from it moves the pane exactly like the header controls do.
  const commandBarHandlersRef = useRef({ handleArchive, changeProjectContext });
  useEffect(() => {
    commandBarHandlersRef.current = { handleArchive, changeProjectContext };
  });
  const commandBarSession = c.currentSession ?? null;
  useRegisterCommandBarContext(
    useMemo(
      () =>
        commandBarSession
          ? {
              kind: "chat",
              session: commandBarSession,
              archive: (session: ChatSession) => commandBarHandlersRef.current.handleArchive(session),
              changeProject: (projectId: string | null) =>
                commandBarHandlersRef.current.changeProjectContext(projectId),
            }
          : null,
      [commandBarSession],
    ),
  );

  // URL → new chat: `?agent=<id>` is the deep link used by "DM" entry points
  // (e.g. the agent detail page) to land on a fresh compose bound to that
  // agent. The permission-filtered agent list loads async, so the intent is
  // consumed on the render where the agent resolves, then the param is
  // stripped so refresh / the session sync above don't replay it. The ref
  // resets once the param is gone so a later identical deep link fires again.
  // A settled miss (access revoked, agent archived, bad id) is a denial: it
  // explains itself with a toast and consumes the intent so a later refetch
  // that surfaces the agent cannot start a chat without a fresh click. While
  // the queries are still loading the intent simply stays pending.
  useEffect(() => {
    if (!isCurrentChatRoute || getCurrentSlug() !== workspaceSlug) return;
    if (!urlAgent) {
      consumedAgentIntent.current = null;
      return;
    }
    if (consumedAgentIntent.current === urlAgent) return;
    const agent = c.availableAgents.find((a) => a.id === urlAgent);
    if (agent) {
      consumedAgentIntent.current = urlAgent;
      startNewChat(agent);
      replace(wsPaths.chat());
      return;
    }
    if (c.agentsSettled) {
      consumedAgentIntent.current = urlAgent;
      toast.error(t(($) => $.page.agent_link_no_access));
      replace(wsPaths.chat());
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps -- consume when the URL param or the resolving agent list changes
  }, [isCurrentChatRoute, workspaceSlug, urlAgent, c.availableAgents, c.agentsSettled]);

  const newChatButton = (
    <NewChatButton
      agents={c.availableAgents}
      userId={c.user?.id}
      onStart={startNewChat}
      side="bottom"
    />
  );

  const listHeader = (
    <PanelHeader as="h1" title={t(($) => $.page.title)} leading={<CollapsedNavTrigger />}>
      {newChatButton}
    </PanelHeader>
  );

  const listBody = (
    <div className="min-h-0 flex-1 px-2 py-1">
      <ChatThreadList
        sessions={c.sessions}
        agents={c.agents}
        activeSessionId={c.activeSessionId}
        onSelectSession={handleSelect}
        onArchive={handleArchive}
      />
    </div>
  );

  const compactConversation = isCompact && (!!c.activeSessionId || composingNew);
  // Nothing to talk to and nothing to reread: the composer would only be a
  // disabled box, so the page explains the prerequisite instead.
  const noAgentPage = c.noAgent && c.sessions.length === 0;
  const noAgentState = (
    <CollectionPageState
      icon={Bot}
      title={t(($) => $.page.no_agent_title)}
      description={t(($) => $.page.no_agent_description)}
      actions={
        <Button size="sm" onClick={() => push(wsPaths.newAgent())}>
          <Plus aria-hidden="true" />
          {t(($) => $.page.no_agent_action)}
        </Button>
      }
    />
  );
  const backToList = () => {
    c.setActiveSession(null);
    setComposingNew(false);
  };

  // The conversation pane: message list / skeleton / empty above a persistent
  // banner + input. Identical composition to the floating window's body, so a
  // brand-new chat (no active session) shows the agent-aware empty state + input.
  // No compose-box agent selector — the agent is fixed when the chat starts.
  // `@container`: the conversation column's gutter (CHAT_GUTTER) widens with
  // THIS pane, which the user resizes independently of the browser window.
  const queuedTasks = c.pendingTask?.queued_tasks ?? [];
  const conversation = (
    <div className="flex flex-1 flex-col min-h-0 @container">
      {c.currentSession && (
        <ChatSessionHeader
          leading={
            compactConversation ? (
              <IconButton
                label={t(($) => $.page.title)}
                tooltipSide="bottom"
                className="text-muted-foreground"
                onClick={backToList}
              >
                <ArrowLeft />
              </IconButton>
            ) : listCollapsed ? (
              <CollapsedNavTrigger />
            ) : undefined
          }
          session={c.currentSession}
          agent={c.activeAgent}
          onArchive={handleArchive}
        />
      )}
      {c.showSkeleton ? (
        <ChatMessageSkeleton />
      ) : c.hasMessages ? (
        <ChatMessageList
          key={c.activeSessionId}
          messages={c.messages}
          pendingTask={c.pendingTask}
          availability={c.availability}
          firstItemIndex={c.firstItemIndex}
          hasOlderMessages={c.hasOlderMessages}
          isFetchingOlderMessages={c.isFetchingOlderMessages}
          onLoadOlderMessages={() => void c.fetchOlderMessages()}
          onQuickAction={(action) => c.handleSend(action.prompt)}
          quickActionsDisabled={
            !!c.pendingTaskId ||
            c.isSessionArchived ||
            c.isAgentArchived ||
            c.isAgentAccessRevoked ||
            !c.isAgentRuntimeBound ||
            c.noAgent
          }
          onRegenerateQuickActions={(message) =>
            c.activeSessionId
              ? regenerateQuickActions.mutateAsync({
                  sessionId: c.activeSessionId,
                  messageId: message.id,
                })
              : undefined
          }
          quickActionsPendingMessageId={quickActionsPending?.message_id ?? null}
          annotations={annotations}
          wakeups={wakeups}
        />
      ) : (
        <EmptyState
          agent={c.activeAgent}
          hasSessions={c.sessions.length > 0}
          onPickPrompt={c.sendConversationStarter}
        />
      )}

      {c.isAgentAccessRevoked ? (
        <AgentAccessRevokedBanner agentName={c.activeAgent?.name} />
      ) : c.noAgent ? (
        <NoAgentBanner />
      ) : c.isAgentArchived ? (
        <ArchivedAgentBanner agentName={c.activeAgent?.name} />
      ) : !c.isAgentRuntimeBound && c.activeAgent ? (
        <RuntimeRequiredBanner
          agentId={c.activeAgent.id}
          agentName={c.activeAgent.name}
        />
      ) : (
        <OfflineBanner agentName={c.activeAgent?.name} availability={c.availability} />
      )}

      <div className="px-4">
        <ChatAppRequests sessionId={c.activeSessionId} />
      </div>

      <ChatWakeupStrip sessionId={c.activeSessionId} wakeups={wakeups} />

      <ChatQueue
        tasks={queuedTasks}
        wakeups={wakeups}
        headStatus={c.pendingTask?.status}
        onSendNow={c.handleSendQueuedTaskNow}
        sendNowDisabled={c.isAgentAccessRevoked}
        onEdit={c.handleEditQueuedTask}
        onRemove={c.handleRemoveQueuedTask}
        onClear={c.handleClearQueuedTasks}
      />

      <ChatInput
        onSend={c.handleSend}
        restoreDraftRequest={c.restoreDraftRequest}
        conversationStarterRequest={c.conversationStarterRequest}
        onConversationStarterApplied={c.handleConversationStarterApplied}
        onRestoreDraftApplied={c.handleRestoreDraftApplied}
        uploadEnabled={c.uploadEnabled && !c.isAgentAccessRevoked}
        onStop={c.handleStop}
        isRunning={!!c.pendingTaskId}
        allowSubmitWhileRunning={c.pendingTask?.supports_queue === true}
        canSteerWhileRunning={c.pendingTask?.can_supplement}
        disabled={
          c.isSessionArchived ||
          c.isAgentArchived ||
          c.isAgentAccessRevoked ||
          !c.isAgentRuntimeBound
        }
        noAgent={c.noAgent}
        agentArchived={c.isAgentArchived}
        agentAccessRevoked={c.isAgentAccessRevoked}
        agentRuntimeRequired={!c.isAgentRuntimeBound}
        agentName={c.activeAgent?.name}
        projects={c.projects}
        projectId={c.activeProjectId}
        projectContextUnsupported={c.projectContextUnsupported}
        onProjectChange={changeProjectContext}
        isProjectUpdating={c.isProjectUpdating}
        focusRequest={c.focusInputRequest}
        annotations={annotations}
      />
    </div>
  );

  // -- Compact: list / conversation toggle -----------------------------------
  if (isCompact) {
    if (compactConversation) {
      // An open session carries the way back in its own header; a new chat
      // has no session header yet, so it gets a bar of its own.
      return (
        <div className="flex flex-1 flex-col min-h-0">
          {!c.currentSession && (
            <div className="flex h-12 shrink-0 items-center border-b px-2">
              <Button
                variant="ghost"
                size="sm"
                onClick={backToList}
                className="gap-1.5 text-muted-foreground"
              >
                <ArrowLeft className="h-4 w-4" />
                {t(($) => $.page.title)}
              </Button>
            </div>
          )}
          {conversation}
        </div>
      );
    }
    return (
      <div className="flex flex-1 flex-col min-h-0">
        {listHeader}
        {noAgentPage ? (
          noAgentState
        ) : (
          <div className="flex min-h-0 flex-1 flex-col">{listBody}</div>
        )}
      </div>
    );
  }

  // -- Desktop: list column + conversation. The conversation pane appears only once
  // there is a chat target — an open thread or a new chat whose agent was just
  // picked via ⊕. With nothing selected there is no agent, so we show a neutral
  // prompt instead of an orphaned compose box. -------------------------------
  const hasTarget = !!c.activeSessionId || composingNew;
  return (
    <div className="flex min-h-0 flex-1">
      <ListColumn collapsed={listCollapsed} width="list">
        {listHeader}
        <div className="flex min-h-0 flex-1 flex-col">{listBody}</div>
      </ListColumn>
      <div className="flex h-full min-h-0 min-w-0 flex-1 flex-col">
        {listCollapsed && !c.currentSession && <PageHeader>{newChatButton}</PageHeader>}
        {hasTarget ? (
          conversation
        ) : noAgentPage ? (
          noAgentState
        ) : (
          <div className="flex min-h-0 flex-1 flex-col items-center justify-center gap-3 text-muted-foreground">
            <MessageSquare className="h-10 w-10 text-faint-foreground" />
            <p className="text-body">{t(($) => $.page.select_prompt)}</p>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useMemo, useRef } from "react";
import { useInfiniteQuery, type InfiniteData, type UseInfiniteQueryResult } from "@tanstack/react-query";
import { toast } from "sonner";
import { chatMessagesPageOptions } from "@workpal/core/chat/queries";
import { useCommentDraftStore, type CommentDraftKey } from "@workpal/core/issues/stores";
import type { ChatMessage, ChatMessagesPage } from "@workpal/core/types";
import { useCommentAnnotations } from "../../issues/components/use-comment-annotations";
import { useT } from "../../i18n";

/** Persisted assistant answers are the only annotatable chat text. */
export function isAnnotatableChatMessage(message: ChatMessage): boolean {
  return message.role === "assistant" && !message.failure_reason &&
    message.message_kind !== "no_response" && !!message.content.trim();
}

/**
 * Registered by the message list: releases the bottom follow and scrolls the
 * message's row into Virtuoso's window. False when the message is not listed.
 */
type RevealChatMessage = (messageId: string) => boolean;

const REVEAL_RETRY_FRAMES = 30;

type MessagesQuery = UseInfiniteQueryResult<InfiniteData<ChatMessagesPage>>;

function hasMessage(pages: readonly ChatMessagesPage[] | undefined, messageId: string): boolean {
  return !!pages?.some((page) => page.messages.some((message) => message.id === messageId));
}

/** Page older history in until the message is loaded or history runs out. */
async function loadOlderUntil(query: MessagesQuery, messageId: string): Promise<boolean> {
  let result = query;
  while (!hasMessage(result.data?.pages, messageId) && result.hasNextPage) {
    // Join a page load the list already started rather than cancelling it.
    result = await result.fetchNextPage({ cancelRefetch: false });
    if (result.isFetchNextPageError) return false;
  }
  return hasMessage(result.data?.pages, messageId);
}

export type ChatAnnotations = ReturnType<typeof useChatAnnotations>;

/** Issue reply annotations, sourced from one chat session's assistant replies. */
export function useChatAnnotations({ sessionId, agentName, enabled }: {
  sessionId: string | null;
  agentName: string | undefined;
  enabled: boolean;
}) {
  const { t } = useT("issues");
  const query = useInfiniteQuery(chatMessagesPageOptions(sessionId ?? ""));
  const queryRef = useRef(query);
  queryRef.current = query;
  const pages = sessionId ? query.data?.pages : undefined;
  const sources = useMemo(
    () => (pages ?? []).flatMap((page) => page.messages)
      .filter(isAnnotatableChatMessage)
      .map((message) => ({ id: message.id, name: agentName ?? "" })),
    [pages, agentName],
  );
  const draftKey: CommentDraftKey = `chat:${sessionId ?? ""}`;
  // The floating chat window is z-50; markers default below it.
  const annotations = useCommentAnnotations({ draftKey, sources, enabled: enabled && !!sessionId, markerZIndex: 50 });
  const revealSourceRef = useRef<RevealChatMessage | null>(null);
  const editRef = useRef(annotations.editAnnotation);
  editRef.current = annotations.editAnnotation;
  const retryFrame = useRef<number | null>(null);
  // Bumped by every navigation so a slow page load cannot open a stale note.
  const attemptRef = useRef(0);
  const cancelRetry = useCallback(() => {
    attemptRef.current += 1;
    if (retryFrame.current !== null) cancelAnimationFrame(retryFrame.current);
    retryFrame.current = null;
  }, []);
  useEffect(() => cancelRetry, [draftKey, cancelRetry]);

  // Rows mount a frame or more after their data lands, and virtualized rows
  // leave the DOM once scrolled away: retry until the source can anchor.
  const openWhenMounted = useCallback((id: string, messageId: string, revealed: boolean) => {
    const attempt = attemptRef.current;
    let frames = 0;
    const retry = () => {
      retryFrame.current = null;
      if (attempt !== attemptRef.current) return;
      if (!revealed) revealed = !!revealSourceRef.current?.(messageId);
      if (revealed && editRef.current(id, true)) return;
      if (++frames >= REVEAL_RETRY_FRAMES) {
        toast.error(t(($) => $.reply.annotations.source_changed));
        return;
      }
      retryFrame.current = requestAnimationFrame(retry);
    };
    retryFrame.current = requestAnimationFrame(retry);
  }, [t]);

  const editAnnotation = useCallback((id: string, scrollToSource = false): boolean => {
    cancelRetry();
    const annotation = useCommentDraftStore.getState().getAnnotations(draftKey).find((a) => a.id === id);
    if (!annotation) return false;
    if (!scrollToSource) return editRef.current(id);
    const messageId = annotation.sourceCommentId;
    // A restored draft can quote a reply older than the pages loaded so far.
    if (!hasMessage(queryRef.current.data?.pages, messageId)) {
      if (!queryRef.current.hasNextPage) return editRef.current(id, true);
      const attempt = attemptRef.current;
      void loadOlderUntil(queryRef.current, messageId).then((found) => {
        if (attempt !== attemptRef.current) return;
        if (found) openWhenMounted(id, messageId, false);
        else toast.error(t(($) => $.reply.annotations.source_changed));
      });
      return true;
    }
    if (!revealSourceRef.current?.(messageId)) return editRef.current(id, true);
    if (editRef.current(id, true)) return true;
    openWhenMounted(id, messageId, true);
    return true;
  }, [draftKey, t, cancelRetry, openWhenMounted]);

  return { ...annotations, draftKey, editAnnotation, revealSourceRef };
}

"use client";

import { useCallback, useEffect, useId, useMemo, useRef, useState } from "react";
import { MessageSquarePlus } from "@workpal/ui/icons";
import { toast } from "sonner";
import { isImeComposing } from "@workpal/core/utils";
import { Button } from "@workpal/ui/components/ui/button";
import { IconButton } from "@workpal/ui/components/common/icon-button";
import { useCommentDraftStore, type CommentDraftKey } from "@workpal/core/issues/stores";
import { MAX_ANNOTATION_QUOTE_LENGTH, MAX_REPLY_ANNOTATIONS, type ReplyAnnotation } from "@workpal/core/drafts/reply-annotation";
import { useT } from "../../i18n";
import { annotationRange, captureCommentSelection, findAnnotationSource } from "./comment-annotation-selection";
import { CommentSelectionBubble } from "./comment-selection-bubble";
import { AnnotationComposer, type AnnotationSendControls } from "./annotation-composer";
import type { ContentEditorRef } from "../../editor/content-editor";

type CapturedSelection = NonNullable<ReturnType<typeof captureCommentSelection>>;
type SourceAnchor = { id: string; range: Range; root: HTMLElement };

export function useCommentAnnotations({ issueId, draftKey, sources, enabled, onAdded, onOpen, editable = false, markerZIndex }: {
  issueId?: string;
  draftKey: CommentDraftKey;
  sources: { id: string; name: string; revision?: number }[];
  enabled: boolean;
  onAdded?: () => void;
  /** Editable descriptions use their existing toolbar to call addSelection. */
  editable?: boolean;
  onOpen?: () => void;
  /** Markers must stack above a floating host such as the chat window. */
  markerZIndex?: number;
}) {
  const { t } = useT("issues");
  const cardRef = useRef<HTMLDivElement | null>(null);
  // The source container may mount after this hook (chat lists render behind
  // a skeleton), so anchoring must re-run when it appears.
  const [card, setCard] = useState<HTMLDivElement | null>(null);
  const setCardRef = useCallback((node: HTMLDivElement | null) => {
    cardRef.current = node;
    setCard(node);
  }, []);
  const inputRef = useRef<ContentEditorRef>(null);
  const submittingRef = useRef<string | null>(null);
  const pendingFocusId = useRef<string | null>(null);
  const actionRef = useRef<HTMLButtonElement>(null);
  const [selection, setSelection] = useState<CapturedSelection | null>(null);
  const [editor, setEditor] = useState<{ annotation: ReplyAnnotation; existing: boolean } | null>(null);
  const editing = editor?.annotation;
  const editingExisting = editor?.existing === true;
  const editingRef = useRef(editing);
  editingRef.current = editing;
  const editingId = editing?.id;
  const [error, setError] = useState(false);
  const [anchors, setAnchors] = useState<SourceAnchor[]>([]);
  const markerRanges = useMemo(() => {
    const groups = new Map<HTMLElement, Range[]>();
    for (const anchor of anchors) {
      const group = groups.get(anchor.root) ?? [];
      group.push(anchor.range); groups.set(anchor.root, group);
    }
    return groups;
  }, [anchors]);
  const annotations = useCommentDraftStore((s) => s.getAnnotations(draftKey));
  const annotationsRef = useRef(annotations);
  annotationsRef.current = annotations;
  const sourcesRef = useRef(sources);
  sourcesRef.current = sources;
  const onOpenRef = useRef(onOpen);
  onOpenRef.current = onOpen;
  const onAddedRef = useRef(onAdded);
  onAddedRef.current = onAdded;
  const anchorKey = annotations.map((a) => a.id).join(",");
  const highlightName = `reply-annotation-${useId().replace(/[^a-zA-Z0-9-]/g, "")}`;

  const close = (restoreFocus = false) => {
    if (submittingRef.current) return;
    if (restoreFocus && selection?.root.isConnected) {
      const target = editable ? selection.root.querySelector<HTMLElement>("[contenteditable=true]") ?? selection.root : selection.root;
      target.focus({ preventScroll: true });
    }
    setSelection(null); setEditor(null); setError(false);
  };
  const readSelection = useCallback(() => {
    if (!enabled || submittingRef.current || !cardRef.current) return null;
    const captured = captureCommentSelection(cardRef.current, window.getSelection(), editable);
    return captured && sourcesRef.current.some((source) => source.id === captured.sourceCommentId) ? captured : null;
  }, [enabled, editable]);
  const capture = () => {
    const captured = readSelection();
    if (captured) { setSelection(captured); setEditor(null); setError(false); }
  };

  useEffect(() => { setSelection(null); setEditor(null); setError(false); submittingRef.current = null; }, [draftKey, enabled]);

  // Dismiss on the next press, never on the click completing the opening drag.
  useEffect(() => {
    if (!selection) return;
    const onPointerDown = (event: PointerEvent) => {
      if (submittingRef.current) return;
      if (event.target instanceof Element &&
        event.target.closest("[data-editor-overlay-owner]")?.getAttribute("data-editor-overlay-owner") === draftKey) return;
      setSelection(null); setEditor(null); setError(false);
    };
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key !== "Escape" || isImeComposing(event) || submittingRef.current) return;
      // A nested menu owns its first Escape; its portal is outside this DOM tree.
      if (event.target instanceof Element &&
        event.target.closest("[data-editor-overlay-owner]")?.getAttribute("data-editor-overlay-owner") === draftKey &&
        !event.target.closest("[data-reply-annotation-overlay]")) return;
      if (selection.root.isConnected) {
        const target = editable ? selection.root.querySelector<HTMLElement>("[contenteditable=true]") ?? selection.root : selection.root;
        target.focus({ preventScroll: true });
      }
      setSelection(null); setEditor(null); setError(false);
    };
    const onFocusIn = (event: FocusEvent) => {
      if (submittingRef.current) return;
      if (!(event.target instanceof Element) || selection.root.contains(event.target) ||
        event.target.closest("[data-editor-overlay-owner]")?.getAttribute("data-editor-overlay-owner") === draftKey) return;
      // Clipboard fallback briefly focuses a hidden textarea, then restores
      // the owned control synchronously. Only dismiss if focus stays outside.
      queueMicrotask(() => {
        const target = document.activeElement;
        if (submittingRef.current || selection.root.contains(target) ||
          target?.closest("[data-editor-overlay-owner]")?.getAttribute("data-editor-overlay-owner") === draftKey) return;
        setSelection(null); setEditor(null); setError(false);
      });
    };
    document.addEventListener("pointerdown", onPointerDown);
    document.addEventListener("keydown", onKeyDown);
    document.addEventListener("focusin", onFocusIn);
    return () => {
      document.removeEventListener("pointerdown", onPointerDown);
      document.removeEventListener("keydown", onKeyDown);
      document.removeEventListener("focusin", onFocusIn);
    };
  }, [selection, draftKey, editable]);

  const focusNote = useCallback(() => {
    if (!editingId || pendingFocusId.current !== editingId) return;
    pendingFocusId.current = null;
    if (window.matchMedia("(pointer: fine)").matches) inputRef.current?.focus();
  }, [editingId]);

  useEffect(() => {
    if ((!anchorKey && !editingId) || !enabled) {
      setAnchors((current) => current.length ? [] : current);
      return;
    }
    if (!card) return;
    const canHighlight = typeof Highlight !== "undefined" && typeof CSS !== "undefined" && !!CSS.highlights;
    const update = () => {
      const next = annotationsRef.current.flatMap((a) => {
        const root = findAnnotationSource(card, a.sourceCommentId);
        const range = root && annotationRange(root, a, editable);
        return root && range ? [{ id: a.id, range, root }] : [];
      });
      setAnchors((current) => !current.length && !next.length ? current : next);
      // Expanding a resolved thread may remount the selected comment's body.
      // Keep the note editor attached to its saved quote, never a detached Range.
      setSelection((current) => {
        if (!current) return current;
        const saved = annotationsRef.current.find((a) => a.sourceCommentId === current.sourceCommentId &&
          a.start === current.start && a.quote === current.quote);
        const anchor = saved && next.find((a) => a.id === saved.id);
        if (anchor) return { ...current, root: anchor.root, range: anchor.range };
        const pending = editingRef.current;
        if (!saved && pending?.sourceCommentId === current.sourceCommentId) {
          const root = findAnnotationSource(card, pending.sourceCommentId);
          const range = root && annotationRange(root, pending, editable);
          return root && range ? { ...current, root, range } : current;
        }
        if (saved) return editingRef.current?.id === saved.id ? current : null;
        return current.root.isConnected && current.range.startContainer.isConnected ? current : null;
      });
      if (canHighlight) CSS.highlights.set(highlightName, new Highlight(...next.map((a) => a.range)));
    };
    update();
    const observer = new MutationObserver((records) => {
      // Reply typing must not re-index a long source comment.
      if (records.some((record) => {
        const target = record.target instanceof Element ? record.target : record.target.parentElement;
        return target?.closest("[data-comment-content]") ||
          [...record.addedNodes, ...record.removedNodes].some((node) => node instanceof Element &&
            (node.matches("[data-comment-content]") || node.querySelector("[data-comment-content]")));
      })) update();
    });
    observer.observe(card, { childList: true, subtree: true, characterData: true });
    return () => { observer.disconnect(); if (canHighlight) CSS.highlights.delete(highlightName); };
  }, [anchorKey, highlightName, draftKey, editable, enabled, editingId, card]);

  useEffect(() => {
    if (!selection || (editor?.existing && !annotations.some((a) => a.id === editingId))) {
      setSelection(null); setEditor(null);
    }
  }, [annotations, editor?.existing, editingId, selection]);

  const editAnnotation = (id: string, scrollToSource = false): boolean => {
    if (submittingRef.current) return false;
    const annotation = annotationsRef.current.find((a) => a.id === id);
    const root = cardRef.current && annotation && findAnnotationSource(cardRef.current, annotation.sourceCommentId);
    const range = root && annotation && annotationRange(root, annotation, editable);
    if (!root || !range || !annotation) return false;
    if (scrollToSource) {
      const element = range.startContainer instanceof Element ? range.startContainer : range.startContainer.parentElement;
      element?.scrollIntoView({ block: "center", behavior: "instant" });
    }
    onOpenRef.current?.();
    pendingFocusId.current = id;
    setSelection({ ...annotation, range, root }); setEditor({ annotation, existing: true }); setError(false);
    return true;
  };

  const add = useCallback((captured: CapturedSelection | null) => {
    if (submittingRef.current) return false;
    const source = captured && sourcesRef.current.find((e) => e.id === captured.sourceCommentId);
    if (!captured || !source) {
      toast.error(t(($) => $.reply.annotations.selection_failed));
      return false;
    }
    const { quote, start, prefix, suffix, sourceCommentId } = captured;
    const duplicate = annotationsRef.current.find((a) => a.sourceCommentId === sourceCommentId &&
      a.start === start && a.quote === quote && a.prefix === prefix && a.suffix === suffix);
    if (quote.length > MAX_ANNOTATION_QUOTE_LENGTH) {
      setError(true);
      toast.error(t(($) => $.reply.annotations.quote_limit, { count: MAX_ANNOTATION_QUOTE_LENGTH }));
      return false;
    }
    onOpenRef.current?.();
    setSelection(captured);
    const next = duplicate ?? {
      id: crypto.randomUUID(), sourceCommentId, sourceActorName: source.name,
      sourceRevision: source.revision, quote, start, prefix, suffix, note: "",
    };
    pendingFocusId.current = next.id;
    setEditor({ annotation: next, existing: !!duplicate });
    setError(false);
    window.getSelection()?.removeAllRanges();
    return true;
  }, [t]);
  const addSelection = useCallback(() => add(readSelection()), [add, readSelection]);

  const confirmNote = (note: string, dismiss: boolean): boolean => {
    if (!editing || !note.trim()) return false;
    const store = useCommentDraftStore.getState();
    const id = editingExisting ? editing.id : store.addAnnotation(draftKey, { ...editing, note });
    if (!id) { setError(true); return false; }
    store.updateAnnotation(draftKey, id, note);
    if (dismiss) close(true);
    else setEditor({ annotation: { ...editing, id, note }, existing: true });
    if (!editingExisting) onAddedRef.current?.();
    return true;
  };

  // Keep the pending quote identifiable without counting it as an annotation.
  useEffect(() => {
    if (!enabled || !selection || !editingId || typeof Highlight === "undefined" ||
      typeof CSS === "undefined" || !CSS.highlights) return;
    const name = `${highlightName}-selection`;
    CSS.highlights.set(name, new Highlight(selection.range));
    return () => { CSS.highlights.delete(name); };
  }, [enabled, selection, editingId, highlightName]);

  const renderComposer = (controls?: AnnotationSendControls) => {
    return enabled && selection ? <CommentSelectionBubble range={selection.range} source={selection.root} owner={draftKey} onPositioned={focusNote} keepVisibleWhenDetached={!!editing}>
        <div className="bubble-menu max-w-[calc(100vw-16px)] focus-within:outline-1 focus-within:outline-ring">
          {editing ? <AnnotationComposer key={editing.id} issueId={issueId} owner={draftKey}
            annotation={editing} existing={editingExisting}
            number={annotations.findIndex((a) => a.id === editing.id) + 1}
            editorRef={inputRef} controls={controls}
            sourceMissing={!sources.some((source) => source.id === editing.sourceCommentId)}
            sourceChanged={sources.some((source) => source.id === editing.sourceCommentId &&
              source.revision !== undefined && editing.sourceRevision !== undefined && source.revision !== editing.sourceRevision)}
            canSave={editingExisting || annotations.length < MAX_REPLY_ANNOTATIONS}
            onChange={(note) => { setEditor({ annotation: { ...editing, note }, existing: editingExisting }); setError(false); }}
            onSave={confirmNote} onBusyChange={(busy) => {
              if (busy && editingRef.current?.id === editing.id) submittingRef.current = editing.id;
              else if (!busy && submittingRef.current === editing.id) submittingRef.current = null;
            }}
            onRemove={editingExisting ? () => {
              useCommentDraftStore.getState().removeAnnotation(draftKey, editing.id);
              close(true);
            } : undefined} /> : <Button ref={actionRef} variant="ghost" size="sm"
              onMouseDown={(event) => event.preventDefault()} onClick={() => add(selection)}>
              <MessageSquarePlus />{t(($) => editable ? $.reply.annotations.add_comment : $.reply.annotations.add)}
            </Button>}
        </div>
        {error && <p role="alert" className="mt-1 max-w-72 rounded-lg bg-popover p-2 text-caption text-destructive shadow-[var(--menu-shadow)]">
          {selection.quote.length > MAX_ANNOTATION_QUOTE_LENGTH
            ? t(($) => $.reply.annotations.quote_limit, { count: MAX_ANNOTATION_QUOTE_LENGTH })
            : t(($) => $.reply.annotations.count_limit, { count: MAX_REPLY_ANNOTATIONS })}
        </p>}
      </CommentSelectionBubble> : null;
  };

  return {
    cardRef: setCardRef,
    editAnnotation,
    addSelection,
    composer: editing ? { pending: editing, render: renderComposer } : undefined,
    captureProps: {
      "data-annotation-thread": draftKey,
      onPointerUp: (event: React.PointerEvent) => {
        if (!editable && event.target instanceof Element && event.target.closest("[data-comment-content]") &&
          !event.target.closest("button, [contenteditable=true]")) capture();
      },
      onKeyUp: (event: React.KeyboardEvent) => {
        if (!editable && event.shiftKey && event.key.startsWith("Arrow")) capture();
      },
      onKeyDown: (event: React.KeyboardEvent) => {
        if (event.key === "Tab" && !event.shiftKey && selection && !editingId &&
          event.target instanceof Element && event.target.closest("[data-comment-content]")) {
          event.preventDefault(); actionRef.current?.focus();
        }
      },
    },
    popup: <>
      {(annotations.length > 0 || editing) && <style>{`::highlight(${highlightName}), ::highlight(${highlightName}-selection) { background: color-mix(in srgb, var(--brand) 20%, transparent); }`}</style>}
      {enabled && anchors.map((anchor) => {
        const index = annotations.findIndex((a) => a.id === anchor.id);
        if (index < 0) return null;
        return <CommentSelectionBubble key={anchor.id} range={anchor.range} source={anchor.root} owner={draftKey}
          markerRanges={markerRanges.get(anchor.root)} markerZIndex={markerZIndex}>
          <IconButton variant="brandSubtle" size="icon-sm" className="size-6 text-caption tabular-nums aria-expanded:ring-2 aria-expanded:ring-brand"
            aria-expanded={editingId === anchor.id}
            label={t(($) => $.reply.annotations.edit, { number: index + 1 })}
            onClick={() => editAnnotation(anchor.id)}>{index + 1}</IconButton>
        </CommentSelectionBubble>;
      })}
      {!editing && renderComposer()}
    </>,
  };
}

import { useEffect } from "react";
import { useQueryClient } from "@tanstack/react-query";
import { chatKeys, QUICK_ACTIONS_PENDING_TIMEOUT_MS } from "./queries";
import type { ChatQuickActionsPendingState } from "../types/chat";

/**
 * Clears a session's `quickActionsPending` marker from the query cache when no
 * chat:quick_actions supplement resolves it before the marker's own deadline
 * (MUL-5149). Unlike a component-local timer, this drops the REAL cache state,
 * so the pill spinner / skeleton stops AND a later refresh — even after closing
 * and reopening chat — starts clean instead of re-reading a stuck marker.
 *
 * The deadline is `marker.expires_at` (absolute), NOT a fresh window per mount:
 * switching between the floating chat and the chat tab unmounts one host and
 * mounts the other, and a per-mount timer would restart the full wait each time,
 * letting a lost event strand the marker indefinitely. Reading the stored
 * deadline means a remount waits only the remaining time. The final clear is
 * message-scoped so it never wipes a newer turn's marker.
 *
 * Mount once per surface that reads the marker (chat page / floating window).
 */
export function useQuickActionsPendingTimeout(
  sessionId: string | null,
  pending: ChatQuickActionsPendingState | null,
): void {
  const qc = useQueryClient();
  const messageId = pending?.message_id ?? null;
  const expiresAt = pending?.expires_at ?? null;
  useEffect(() => {
    if (!sessionId || !messageId) return;
    const clear = () =>
      qc.setQueryData<ChatQuickActionsPendingState | null>(
        chatKeys.quickActionsPending(sessionId),
        (current) =>
          current && current.message_id === messageId ? null : current,
      );
    // Remaining time to this marker's absolute deadline; an old marker without
    // one falls back to a full window. Already-past deadlines clear next tick.
    const remaining =
      expiresAt != null
        ? expiresAt - Date.now()
        : QUICK_ACTIONS_PENDING_TIMEOUT_MS;
    const timer = setTimeout(clear, Math.max(0, remaining));
    return () => clearTimeout(timer);
  }, [qc, sessionId, messageId, expiresAt]);
}

import { useEffect } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import {
  chatKeys,
  chatQuickActionsFailureOptions,
} from "@workpal/core/chat/queries";
import type { ChatQuickActionsFailureState } from "@workpal/core/types";
import { toast } from "sonner";
import { useT } from "../../i18n";

/**
 * Surfaces a toast when a session's explicit quick-actions refresh fails
 * asynchronously — the HTTP call was accepted but the daemon's regeneration
 * never produced suggestions, so the turn's pills are unchanged (MUL-5149). The
 * failure arrives over chat:quick_actions with failed=true, which
 * applyChatQuickActionsToCache turns into a one-shot client-only signal; this
 * hook consumes it and clears it. The synchronous HTTP-failure path (409 busy,
 * network) already toasts from QuickActions.handleRegenerate, so this covers
 * only the async half — without it, a failed refresh would look identical to a
 * successful one whose suggestions happened not to change.
 *
 * A stable toast id keyed on the failure nonce collapses duplicates when both
 * chat surfaces (floating window + chat tab) are mounted and each runs this
 * hook against the same signal. Mount once per surface that reads the marker.
 */
export function useQuickActionsFailureToast(sessionId: string | null): void {
  const qc = useQueryClient();
  const { t } = useT("chat");
  const { data: failure = null } = useQuery(
    chatQuickActionsFailureOptions(sessionId ?? ""),
  );

  useEffect(() => {
    if (!sessionId || !failure) return;
    toast.error(t(($) => $.message_list.quick_actions_regenerate_failed), {
      id: `qa-refresh-fail:${sessionId}:${failure.at}`,
    });
    // Clear only this exact signal so a newer failure raised in the same tick
    // is not swallowed.
    qc.setQueryData<ChatQuickActionsFailureState | null>(
      chatKeys.quickActionsFailure(sessionId),
      (current) => (current && current.at === failure.at ? null : current),
    );
  }, [qc, t, sessionId, failure]);
}

"use client";

import { useEffect, useId } from "react";
import {
  useCommandBarContextStore,
  useRecentVisitsStore,
  type CommandBarContext,
  type RecentVisitType,
} from "@workpal/core/command-bar";

function recentVisitOf(
  context: CommandBarContext | null,
): { wsId: string; type: RecentVisitType; id: string } | null {
  switch (context?.kind) {
    case "project":
      return { wsId: context.project.workspace_id, type: "project", id: context.project.id };
    case "agent":
      return { wsId: context.agent.workspace_id, type: "agent", id: context.agent.id };
    case "autopilot":
      return { wsId: context.autopilot.workspace_id, type: "autopilot", id: context.autopilot.id };
    default:
      return null;
  }
}

/**
 * Tell the command bar what this page is about. Pass `null` while the object
 * is still loading. The context must be memoized: a new object re-registers.
 *
 * Project, agent and autopilot pages also land in the bar's Recent group.
 */
export function useRegisterCommandBarContext(context: CommandBarContext | null) {
  const token = useId();

  useEffect(() => {
    const store = useCommandBarContextStore.getState();
    if (context) store.register(token, context);
    else store.unregister(token);
  }, [token, context]);

  useEffect(
    () => () => useCommandBarContextStore.getState().unregister(token),
    [token],
  );

  const visit = recentVisitOf(context);
  const wsId = visit?.wsId ?? null;
  const visitType = visit?.type ?? null;
  const visitId = visit?.id ?? null;
  useEffect(() => {
    if (!wsId || !visitType || !visitId) return;
    useRecentVisitsStore.getState().recordVisit(wsId, { type: visitType, id: visitId });
  }, [wsId, visitType, visitId]);
}

"use client";

import {
  createContext,
  use,
  useCallback,
  useEffect,
  useMemo,
  useState,
  useTransition,
} from "react";
import type { NavigationAdapter } from "./types";

const NavigationContext = createContext<NavigationAdapter | null>(null);
const NavigationPendingContext = createContext<boolean>(false);

/** `+1` while a reported swap is in flight, `-1` when it settles. */
type PendingReporter = (delta: 1 | -1) => void;
const NavigationPendingReportContext = createContext<PendingReporter | null>(
  null,
);

export function NavigationProvider({
  value,
  children,
}: {
  value: NavigationAdapter;
  children: React.ReactNode;
}) {
  // Wrap push/replace in startTransition so any caller of useNavigation()
  // (sidebar AppLink, command palette, modal post-create jumps) gets a
  // React pending signal during route commit. On web this stays true until
  // Next.js commits the new RSC payload; on desktop it flips off quickly
  // because react-router commits synchronously — both are correct.
  const [isPending, startTransition] = useTransition();
  // Second pending source: in-page content swaps reported through
  // `useReportNavigating`. The transition above only spans the adapter's
  // push/replace, which on desktop is a synchronous store write — it is
  // already settled while the destination content is still being rendered,
  // so on its own it can never keep the progress bar on screen there.
  const [reportedPending, setReportedPending] = useState(0);
  const report = useCallback<PendingReporter>((delta) => {
    setReportedPending((n) => Math.max(0, n + delta));
  }, []);
  const wrapped = useMemo<NavigationAdapter>(
    () => ({
      ...value,
      push: (path: string) => startTransition(() => value.push(path)),
      replace: (path: string) => startTransition(() => value.replace(path)),
    }),
    [value],
  );
  return (
    <NavigationContext.Provider value={wrapped}>
      <NavigationPendingReportContext.Provider value={report}>
        <NavigationPendingContext.Provider
          value={isPending || reportedPending > 0}
        >
          {children}
        </NavigationPendingContext.Provider>
      </NavigationPendingReportContext.Provider>
    </NavigationContext.Provider>
  );
}

/**
 * Non-throwing read of the adapter. For components that legitimately render
 * outside a provider — leaf editor UI mounted in isolation, and the tests that
 * exercise it — where the navigation-dependent behaviour has a sane fallback.
 * Anything that must navigate should use `useNavigation()` and keep the throw.
 */
export function useOptionalNavigation(): NavigationAdapter | null {
  return use(NavigationContext);
}

export function useNavigation(): NavigationAdapter {
  const ctx = use(NavigationContext);
  if (!ctx)
    throw new Error("useNavigation must be used within NavigationProvider");
  return ctx;
}

/**
 * True while a transition-wrapped push/replace is committing, or while any
 * mounted view is reporting an in-page content swap.
 */
export function useIsNavigating(): boolean {
  return use(NavigationPendingContext);
}

/**
 * Report an in-page content swap to the shell's `<NavigationProgress />`.
 *
 * For destinations that never change the route — the inbox's detail pane is
 * the case this exists for. There the click updates the list highlight and
 * the URL immediately and the expensive part (mounting the new issue detail)
 * runs behind a `useDeferredValue`, so nothing the navigation adapter can see
 * is still pending while the user waits. Pass that gap in here and the same
 * bar a real route change gets covers it.
 *
 * Safe to call outside a `NavigationProvider` (leaf views mounted in
 * isolation, and their tests) — it simply reports nowhere.
 */
export function useReportNavigating(pending: boolean): void {
  const report = use(NavigationPendingReportContext);
  useEffect(() => {
    if (!pending || !report) return;
    report(1);
    return () => report(-1);
  }, [pending, report]);
}
